import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    scope {
        let t = task effect io {
            defer { io.println("deferred") }
            io.println("body")
        }
        let _ = t.await()
    }
    return Ok(())
}
